INSERT INTO `endpointman_custom_configs` VALUES (1,'y0000000000$suffix.cfg','y0000000000$suffix.cfg','82','[ cfg:/phone/config/system.ini,reboot=1 ]\nLocalTime.TimeZone = {$timezone}\nLocalTime.TimeServer1 = {$network_time_server}\nLocalTime.TimeServer2 = pool.ntp.org\nLocalTime.Interval = 1000\nLocalTime.TimeFormat = 0\nLocalTime.DateFormat = 0\n\nAutoProvision.bEnablePowerOn = 1\nAutoProvision.bEnableWeekly = 0\nAutoProvision.bEnableDHCPOption = 1\nAutoProvision.listSystemOptions = 66,43\nAutoProvision.strServerURL = tftp://{$server.ip.1}\n\ntelnet.telnet_enable = 0\n\n[ cfg:/phone/config/system.ini,reboot=1]\nProfile.CNG = 0\nProfile.VAD = 1\nProfile.Echo = 1\nProfile.SIDE_TONE = -30\n\n[ cfg:/phone/config/user.ini,reboot=1 ]\nWatchDog.Time = 10\nvpm_tone_Country.Country = {$tones_country}\n\nAlertInfo0.Text = interal\nAlertInfo0.Ringer = 2\n\nAlertInfo1.Text = external\nAlertInfo1.Ringer = 5\n\nEmergency.Num = 000\n\nPhoneSetting.BacklightTime = 120\nPhoneSetting.DialNowDelay = {$dialnowdelay}\nPhoneSetting.BackGrounds = {$uselogo}\nPhoneSetting.BackLight = 6\nPhoneSetting.UnusedBackLight = 1\nPhoneSetting.ScreensaverTime = {$screensaverdelay}\nPhoneSetting.Theme = {$theme}\nPhoneSetting.Voicevolume = 5\nPhoneSetting.Lock = 0\n\n[ bin:/phone/config/DialNow.xml,reboot=0 ]\nurl=tftp://{$server.ip.1}/dialnow.xml\n\n[ psw:/phone/config/.htpasswd ]\nadmin = {$adminpw}\n\n[ rom:Firmware ]\nurl = {$firmware_name}'),(2,'y000000000000.boot','y0000000000$suffix.cfg','82','#!version:1.0.0.1\n\n## The header above must appear as-is in the first line\n\ninclude:config \\\"y000000000052.cfg\\\"\n\n#include:config \\\"users.cfg\\\"\n\ninclude:config \\\"$mac.cfg\\\"\n\noverwrite_mode = {$yealink_overwrite_mode}\n'),(3,'y000000000052.cfg','y0000000000$suffix.cfg','82','#!version:1.0.0.1\n\n#firmware.url = tftp://10.1.10.21/T21P_E2-52.84.14.5.rom\n\n# Включить Auto Provisioning:\n\nauto_provision.mode = 1\n\n# Адрес сервера Auto Provisioning (tftp)\n\nauto_provision.server.url = {$server_host}\n\nnetwork.internet_port.type = 0\n\nnetwork.bridge_mode = 0\n\nnetwork.web_server_type = 0\n\n#Устанавливаем свой пароль на вход через Web и телефон\n\nsecurity.user_name.admin = admin\n\nsecurity.user_password = admin:3478\n\nsecurity.user_name.user = user\nsecurity.user_password = user:3478\n\n#Выключить появление логотипа Yealink на телефоне\n\nphone_setting.lcd_logo.mode = 0\n\n#Подсветка\n\nphone_setting.backlight_time = 1800\n\n#https://IP&DNS - user&pass - Account - Rasshirennie - Session Expires (default: 1800)\n\naccount.1.session_timer.expires = 180\n\n# Укажем NTP сервер:\n\nlocal_time.ntp_server1 = polygon.com\n\nlocal_time.interval = 60\n\n# Назначим Time Offset (Московское время)\n\nlocal_time.time_zone = +3\n\nlocal_time.time_zone_name = Russia(Moscow)\n\nlang.wui = Russian\n\nlang.gui = Russian\n\nnetwork.port.max_rtpport = 30000\n\nnetwork.port.min_rtpport = 10000\n\nnetwork.vlan.internet_port_enable = 0\n\nnetwork.vlan.internet_port_vid = 0\n\nnetwork.vlan.dhcp_enable = 0\n\n### LDAP\nldap.enable = 1\nldap.customize_label = AD TelBook\nldap.name_filter = displayName=%\nldap.number_filter = (|(telephoneNumber=%)(mobile=%))\nldap.tls_mode = 0\n###где значение — 0, 1, 2,\n###0 — LDAP; 1 — LDAP TLS start; 2 — LDAPs.\nldap.host = 10.1.10.21\nldap.port = 389\nldap.user = ldapuser@rusagroeco.ru\nldap.password = H9w0ZFmg%\nldap.base = OU=rnd,DC=rusagroeco,DC=ru\nldap.max_hits = 500\nldap.name_attr = displayName\nldap.numb_attr = telephoneNumber mobile ipPhone\nldap.display_name = %displayName\nldap.version = 3\nldap.call_out_lookup = 1\nldap.call_in_lookup = 1\nldap.ldap_sort = 1\n\n');
